import{z as B,x as A,o as t,c as i,q as r,j as o,D as a,d as E,s as n,S as l}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"Borg 与 Kubernetes","description":"","frontmatter":{"title":"Borg 与 Kubernetes","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/borg-kubernetes.md","filePath":"cs/borg-kubernetes.md","lastUpdated":1791413859000}'),d={name:"cs/borg-kubernetes.md"};function p(c,e,u,g,b,_){const s=A("Mermaid");return t(),i("div",null,[e[2]||(e[2]=r('<h1 id="borg-与-kubernetes" tabindex="-1">Borg 与 Kubernetes <a class="header-anchor" href="#borg-与-kubernetes" aria-label="Permalink to &quot;Borg 与 Kubernetes&quot;">​</a></h1><div class="epigraph"><p>集群操作系统：调度把任务放到机器上，控制面是强一致的小状态，数据面是最终一致的调和。声明式对象不等于一次 RPC 的线性化点。</p><footer>—— 据 Verma et al., Large-scale cluster management at Google with Borg, EuroSys 2015；Burns et al., Borg, Omega, and Kubernetes, CACM 2016 整理</footer></div><p>上一课<a href="/cs/distributed-fs-metadata">分布式文件元数据</a>给了卷的一种来源。缺口是<strong>谁把进程放到哪台机器</strong>：调度、隔离、控制器。本课钉 Borg 与 Kubernetes 的控制面形状，不重写 Linux cgroup。后课 Tail at Scale 解释为何调度与多租户制造长尾。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Borg：作业、任务、配额、抢占、机器失败就在别处重启。单元（cell）里有 Borgmaster 复制状态。Kubernetes：API 对象存 etcd（<a href="/cs/etcd-chubby">etcd/Chubby</a>），控制器 watch 后调和到期望态——调和循环是<a href="/cs/eventual-consistency">最终一致</a>，etcd 里对象写是线性一致。缺口：把 <code>kubectl apply</code> 当全集群瞬间完成。调度器看到的是缓存的快照，决策可过时，靠再调和。</p><p>Omega 的共享状态调度、乐观并发是亲戚，Burns 文对照三代。</p><p><span class="marginnote">术语翻译：<strong>声明式</strong>就是「只报要求，不报步骤」——你说「要 3 个副本」，而不是「去机器 5 上启动容器 1、2、3」。<strong>调和循环</strong>则是控制器不停地干一件事：对比期望态与实际态，有差就补。</span></p><p><span class="marginnote">EuroSys 2015 讲 Borg 生产。CACM 2016 讲设计迁移。本课不把 YAML 当理论。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>控制面：少数主，CP。kubelet/代理：本机，失败隔离。调度：过滤 + 打分；绑定写回 etcd 带资源版本（乐观锁）。抢占与优先级处理过载，不是限流课的令牌桶，但同族。</p>',10)),(t(),o(l,null,{default:a(()=>[n(s,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20API%5B%22API%20%2F%20etcd%22%5D%20--%3E%20SCH%5B%22%E8%B0%83%E5%BA%A6%E5%99%A8%22%5D%0A%20%20SCH%20--%3E%20BIND%5B%22%E7%BB%91%E5%AE%9A%E8%8A%82%E7%82%B9%22%5D%0A%20%20CTL%5B%22%E6%8E%A7%E5%88%B6%E5%99%A8%22%5D%20--%3E%20REC%5B%22%E8%B0%83%E5%92%8C%E5%BE%AA%E7%8E%AF%22%5D%0A%20%20REC%20--%3E%20API%0A%20%20KUBE%5B%22kubelet%22%5D%20--%3E%20RUN%5B%22%E8%B7%91%E5%AE%B9%E5%99%A8%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[E(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=r('<p>不要把滚动升级（后课）当成调度算法本身；它是控制器对副本集的调和。</p><p><span class="marginnote">直觉类比：调度器的「过滤 + 打分」像招聘——先硬性筛掉不合格简历（内存不够、端口冲突的机器直接出局），再给剩下的按软指标打分（负载低、镜像已缓存者加分），分高者上岗。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>故障：机器没心跳，任务被重新调度，本地盘要当临时。与<a href="/cs/leases">租约</a>：节点心跳是检测器。脑裂：两个调度器若不用资源版本会双绑——etcd 条件写是 fencing。</p><p>本课不写服务网格。也不写 LLM 训练作业调度。</p><p>多租户尾延迟：邻居 noisy，cgroup 不完美，这是 Tail at Scale 的输入。隔离档（best effort vs guaranteed）是 Borg 已有分类。</p><p>两个调度器同时盯上同一台机器，为什么不会双绑？靠 etcd 条件写：</p>',7)),(t(),o(l,null,{default:a(()=>[n(s,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E6%96%B0%20Pod%20%E5%BE%85%E8%B0%83%E5%BA%A6%22%5D%20--%3E%20S1%5B%22%E8%B0%83%E5%BA%A6%E5%99%A8%20A%20%E6%8F%90%E8%AE%AE%E8%8A%82%E7%82%B9%20X%22%5D%0A%20%20P%20--%3E%20S2%5B%22%E8%B0%83%E5%BA%A6%E5%99%A8%20B%20%E4%B9%9F%E6%8F%90%E8%AE%AE%E8%8A%82%E7%82%B9%20X%22%5D%0A%20%20S1%20--%3E%20W%5B%22%E6%9D%A1%E4%BB%B6%E5%86%99%EF%BC%9A%E7%89%88%E6%9C%AC%E5%8C%B9%E9%85%8D%EF%BC%8C%E7%BB%91%E5%AE%9A%E6%88%90%E5%8A%9F%22%5D%0A%20%20S2%20--%3E%20L%5B%22%E6%9D%A1%E4%BB%B6%E5%86%99%EF%BC%9A%E8%B5%84%E6%BA%90%E7%89%88%E6%9C%AC%E5%B7%B2%E5%8F%98%EF%BC%8C%E5%A4%B1%E8%B4%A5%22%5D%0A%20%20L%20--%3E%20R%5B%22%E9%87%8D%E8%AF%BB%E5%BF%AB%E7%85%A7%EF%BC%8C%E6%8D%A2%E8%8A%82%E7%82%B9%E5%86%8D%E8%AF%95%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[E(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=r('<p><span class="marginnote">常见误区：<code>kubectl apply</code> 返回成功只说明对象写进了 etcd，不等于 Pod 已在跑。从写入到容器 Running 之间隔着调度、拉镜像、启动探针好几步，各步都可失败并被调和重试。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不列全部 API 对象。后课默认：编排 = 强一致存储 + 最终一致调和；读到「已 Running」不表示所有副本同时切完。下一课把规模下的尾从机房层再钉一次。地理复制课处理多集群，不在本课。</p><p>声明式把重试变成调和。调和不是 2PC。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Borg/k8s：控制面 CP，控制器最终一致调和。</li><li>调度绑定用对象版本防双绑。</li><li>机器失败靠检测与在别处重启，本地状态要可丢。</li><li>出处：Verma et al., EuroSys 2015；Burns et al., CACM 2016。</li></ul>',6))])}const C=B(d,[["render",p]]);export{h as __pageData,C as default};
